add_action( 'template_redirect', 'perfectpixel_prefill_cart_for_visitors' );

function perfectpixel_prefill_cart_for_visitors() {
	$product_id = (int) '{{prefill_product_id}}';
	if ( ! $product_id || is_admin() || ! function_exists( 'WC' ) || ! WC()->cart || ! WC()->session ) {
		return;
	}
	if ( WC()->session->get( 'perfectpixel_prefilled' ) ) {
		return; // Already done once; respect a customer who removed it.
	}
	WC()->session->set( 'perfectpixel_prefilled', 1 );
	if ( ! WC()->session->has_session() ) {
		WC()->session->set_customer_session_cookie( true );
	}
	WC()->cart->add_to_cart( $product_id );
}
